CREATE TABLE notification(id BIGINT AUTO_INCREMENT PRIMARY KEY,event_id CHAR(36) NOT NULL,recipient_id BIGINT NOT NULL,type VARCHAR(40) NOT NULL,business_id BIGINT NOT NULL,title VARCHAR(120) NOT NULL,body VARCHAR(1000) NOT NULL,occurred_at TIMESTAMP(6) NOT NULL,payload_hash CHAR(64) NOT NULL,is_read BOOLEAN NOT NULL DEFAULT FALSE,UNIQUE KEY uq_event_recipient(event_id,recipient_id),INDEX idx_user_notice(recipient_id,id));
